17	import { Card, CardTitle, createColumnHelper, DataTable, TableCell, TableRow } from '@bloodhoundenterprise/doodleui';
18	import { Trash } from 'lucide-react';
19	import { useState } from 'react';
20	import { SearchInput } from '../../components';
21	import { useExtensionsQuery } from '../../hooks';
22	
23	const columnHelper = createColumnHelper<any>();
24	
25	export const columns = [
26	    columnHelper.accessor('name', {
27	        id: 'name',
28	        header: () => <span className='pl-6'>Name</span>,
29	        cell: ({ row }) => <span className='pl-6'>{row.original.name}</span>,
30	    }),
31	    columnHelper.accessor('version', {
32	        id: 'version',
33	        header: () => <span className=''>Version</span>,
34	        cell: ({ row }) => <span>{row.original.version}</span>,
35	    }),
36	    columnHelper.accessor('delete', {
37	        id: 'delete-item',
38	        // This is a hack to make the column header not visible but still accessible for screen readers
39	        // Also keeps last column consistent width when no rows are rendered
40	        header: () => <span className='opacity-0'>Delete</span>,
41	        cell: ({ row }) => (
42	            <button aria-label={`Delete ${row.original.name}`}>
43	                <Trash size={18} />
44	            </button>
45	        ),
46	        size: 0,
47	    }),
48	];
49	
50	export const ERROR_MESSAGE = 'There was an error fetching extensions';
51	export const LOADING_MESSAGE = 'Loading extensions...';
52	export const NO_DATA_MESSAGE = 'There are currently no active extensions';
53	export const NO_SEARCH_RESULTS_MESSAGE = 'No extensions match your search terms';
54	
55	const TABLE_CELL_HEIGHT = 57;
56	const TABLE_HEADER_HEIGHT = 52;
57	const EMPTY_STATE_HEIGHT = `${TABLE_HEADER_HEIGHT + TABLE_CELL_HEIGHT * 2}px`;
58	
59	export const ActiveExtensionsCard = () => {
60	    const [search, setSearch] = useState('');
61	    const { data = [], isError, isLoading, isSuccess } = useExtensionsQuery();
62	
63	    const hasData = !isLoading && isSuccess && data.length > 0;
64	    const filteredData = data.filter((extension) => extension.name.toLowerCase().includes(search.toLowerCase()));
65	    const isEmptySearch = hasData && filteredData.length === 0;
66	
67	    let fallbackMessage = LOADING_MESSAGE;
68	
69	    if (isError) {
70	        fallbackMessage = ERROR_MESSAGE;
71	    } else if (isSuccess && !hasData) {
72	        fallbackMessage = NO_DATA_MESSAGE;
73	    } else if (isEmptySearch) {
74	        fallbackMessage = NO_SEARCH_RESULTS_MESSAGE;
75	    }
76	
77	    return (
78	        <Card className='flex flex-col gap-4 overflow-hidden'>
79	            <header className='flex justify-between pt-6 px-6 gap-3'>
80	                <CardTitle className='text-base'>Active Extensions</CardTitle>
81	                <SearchInput
82	                    className='self-start w-80'
83	                    id='search-active-extensions'
84	                    onInputChange={setSearch}
85	                    value={search}
86	                />
87	            </header>
88	
89	            <div
90	                // DataTable currently has some issues with table and cell height within a Card element
91	                // Tailwind doesn't have a way to calculate dynamic heights, so inline styles are used
92	                style={{
93	                    minHeight:
94	                        !hasData || isEmptySearch
95	                            ? EMPTY_STATE_HEIGHT
96	                            : `${TABLE_HEADER_HEIGHT + TABLE_CELL_HEIGHT * filteredData.length}px`,
97	                }}>
98	                <DataTable
99	                    data={filteredData}
100	                    noResultsFallback={
101	                        <TableRow>
102	                            <TableCell colSpan={3} className='h-28 text-center'>
103	                                {fallbackMessage}
104	                            </TableCell>
105	                        </TableRow>
106	                    }
107	                    columns={columns}
108	                />
109	            </div>
110	        </Card>
111	    );
112	};
113

