17	import userEvent from '@testing-library/user-event';
18	import { Extension } from 'js-client-library';
19	import { rest } from 'msw';
20	import { setupServer } from 'msw/node';
21	import { render, screen, waitFor } from '../../test-utils';
22	import {
23	    ActiveExtensionsCard,
24	    ERROR_MESSAGE,
25	    NO_DATA_MESSAGE,
26	    NO_SEARCH_RESULTS_MESSAGE,
27	} from './ActiveExtensionsCard';
28	
29	const mockExtensions: Extension[] = [
30	    { id: '1', name: 'Active Directory', version: 'v0.0.1' },
31	    { id: '2', name: 'Azure', version: 'v1.0.0' },
32	    { id: '3', name: 'Custom Extension', version: '0.5.0' },
33	];
34	
35	const server = setupServer(
36	    rest.get(`/api/v2/extensions`, (_req, res, ctx) =>
37	        res(
38	            ctx.json({
39	                data: { extensions: mockExtensions },
40	            })
41	        )
42	    )
43	);
44	
45	beforeAll(() => server.listen());
46	afterEach(() => server.resetHandlers());
47	afterAll(() => server.close());
48	
49	describe('ActiveExtensionsCard', () => {
50	    it('renders the card with title and search input', () => {
51	        render(<ActiveExtensionsCard />);
52	
53	        expect(screen.getByText('Active Extensions')).toBeInTheDocument();
54	        expect(screen.getByLabelText('Search')).toBeInTheDocument();
55	    });
56	
57	    it('displays a loading message while fetching extensions', () => {
58	        render(<ActiveExtensionsCard />);
59	
60	        expect(screen.getByText('Loading extensions...')).toBeInTheDocument();
61	    });
62	
63	    it('displays an error message while fetching fails', async () => {
64	        server.use(
65	            rest.get(`/api/v2/extensions`, (req, res, ctx) => {
66	                return res(ctx.status(500));
67	            })
68	        );
69	
70	        render(<ActiveExtensionsCard />);
71	
72	        expect(await screen.findByText(ERROR_MESSAGE)).toBeInTheDocument();
73	    });
74	
75	    it('displays no data message when there are no extensions', async () => {
76	        server.use(
77	            rest.get(`/api/v2/extensions`, (_req, res, ctx) => res.once(ctx.json({ data: { extensions: [] } })))
78	        );
79	
80	        render(<ActiveExtensionsCard />);
81	
82	        expect(await screen.findByText(NO_DATA_MESSAGE)).toBeInTheDocument();
83	    });
84	
85	    it('displays extensions in a table when data is available', async () => {
86	        render(<ActiveExtensionsCard />);
87	
88	        expect(await screen.findByText('Active Directory')).toBeInTheDocument();
89	        expect(screen.getByText('v0.0.1')).toBeInTheDocument();
90	        expect(screen.getByText('Azure')).toBeInTheDocument();
91	        expect(screen.getByText('v1.0.0')).toBeInTheDocument();
92	        expect(screen.getByText('Custom Extension')).toBeInTheDocument();
93	        expect(screen.getByText('0.5.0')).toBeInTheDocument();
94	    });
95	
96	    it('renders delete buttons for each extension', async () => {
97	        render(<ActiveExtensionsCard />);
98	
99	        expect(await screen.findByLabelText('Delete Active Directory')).toBeInTheDocument();
100	        expect(screen.getByLabelText('Delete Azure')).toBeInTheDocument();
101	        expect(screen.getByLabelText('Delete Custom Extension')).toBeInTheDocument();
102	    });
103	
104	    it('filters extensions based on search input', async () => {
105	        const user = userEvent.setup();
106	
107	        render(<ActiveExtensionsCard />);
108	
109	        const searchInput = screen.getByLabelText('Search');
110	        await user.type(searchInput, 'Azure');
111	
112	        await waitFor(() => {
113	            expect(screen.getByText('Azure')).toBeInTheDocument();
114	            expect(screen.queryByText('Active Directory')).not.toBeInTheDocument();
115	            expect(screen.queryByText('Custom Extension')).not.toBeInTheDocument();
116	        });
117	    });
118	
119	    it('performs case-insensitive search', async () => {
120	        const user = userEvent.setup();
121	
122	        render(<ActiveExtensionsCard />);
123	
124	        const searchInput = screen.getByLabelText('Search');
125	        await user.type(searchInput, 'azure');
126	
127	        await waitFor(() => {
128	            expect(screen.getByText('Azure')).toBeInTheDocument();
129	            expect(screen.queryByText('Active Directory')).not.toBeInTheDocument();
130	        });
131	    });
132	
133	    it('displays no search results message when search yields no matches', async () => {
134	        const user = userEvent.setup();
135	
136	        render(<ActiveExtensionsCard />);
137	
138	        const searchInput = screen.getByLabelText('Search');
139	        await user.type(searchInput, 'NonExistent');
140	
141	        await waitFor(() => {
142	            expect(screen.getByText(NO_SEARCH_RESULTS_MESSAGE)).toBeInTheDocument();
143	        });
144	    });
145	
146	    it('shows all extensions when search is cleared', async () => {
147	        const user = userEvent.setup();
148	
149	        render(<ActiveExtensionsCard />);
150	
151	        const searchInput = screen.getByLabelText('Search');
152	        await user.type(searchInput, 'Azure');
153	
154	        await waitFor(() => {
155	            expect(screen.getByText('Azure')).toBeInTheDocument();
156	            expect(screen.queryByText('Custom Extension')).not.toBeInTheDocument();
157	        });
158	
159	        await user.clear(searchInput);
160	
161	        await waitFor(() => {
162	            expect(screen.getByText('Azure')).toBeInTheDocument();
163	            expect(screen.getByText('Active Directory')).toBeInTheDocument();
164	            expect(screen.getByText('Custom Extension')).toBeInTheDocument();
165	        });
166	    });
167	
168	    it('applies correct dynamic height based on filtered data', async () => {
169	        const { container } = render(<ActiveExtensionsCard />);
170	
171	        await screen.findByText('Active Directory');
172	
173	        const tableContainer = container.querySelector('div[style*="min-height"]');
174	        expect(tableContainer).toBeInTheDocument();
175	        // With 3 extensions: TABLE_HEADER_HEIGHT (52) + TABLE_CELL_HEIGHT (57) * 3 = 223px
176	        expect(tableContainer).toHaveStyle({ minHeight: '223px' });
177	    });
178	
179	    it('applies empty state height when no results', async () => {
180	        server.use(
181	            rest.get(`/api/v2/extensions`, (_req, res, ctx) => res.once(ctx.json({ data: { extensions: [] } })))
182	        );
183	
184	        const { container } = render(<ActiveExtensionsCard />);
185	
186	        await screen.findByText(NO_DATA_MESSAGE);
187	
188	        const tableContainer = container.querySelector('div[style*="min-height"]');
189	        expect(tableContainer).toBeInTheDocument();
190	    });
191	});
