32	/** Make method that wraps an action creator with dispatch */
33	const curryWithDispatch = (dispatch: React.Dispatch<NotificationAction> | null) => {
34	    return <T extends (...args: any[]) => any>(actionCreator: T) => {
35	        return (...args: Parameters<T>) => {
36	            if (dispatch) {
37	                dispatch(actionCreator(...args));
38	            }
39	        };
40	    };
41	};
