43	export const useNotifications = () => {
44	    const notifications = useContext(NotificationsContext);
45	    const dispatch = useContext(NotificationsDispatchContext);
46	
47	    const actions = useMemo(() => {
48	        const withDispatch = curryWithDispatch(dispatch);
49	        return {
50	            addNotification: withDispatch(addNotificationAction),
51	            dismissNotification: withDispatch(dismissNotificationAction),
52	            removeNotification: withDispatch(removeNotificationAction),
53	        };
54	    }, [dispatch]);
55	
56	    return {
57	        notifications,
58	        ...actions,
59	    };
60	};
